# Definition for a Node.
class Node:
    def __init__(self, val, children=None):
        self.val = val
        self.children = children if children is not None else []

def preorder(root):
    result = []
    def dfs(node):
        if node is None:
            return
        # Visit current node
        result.append(node.val)
        # Traverse all children, left to right
        for child in node.children:
            dfs(child)
    dfs(root)
    return result
